/** Ottoman: steps of 20–33 years from 1475 to 1799, with Wallachia, Moldavia (to the Dniester and
 *  Chernivtsi) and Transylvania with the Partium left out; the Banat and Dobruja stay Ottoman. */
const OTT_PLAN = [
  [1475, 'O1475'], [1499, 'O1475'], [1500, 'O1500'], [1519, 'O1500'], [1520, 'O1520'], [1539, 'O1520'],
  [1540, 'O1540'], [1559, 'O1540'], [1560, 'O1560'], [1579, 'O1560'], [1580, 'O1580'], [1599, 'O1580'],
  [1600, 'O1600'], [1624, 'O1600'], [1625, 'O1625'], [1649, 'O1625'], [1650, 'O1650'], [1682, 'O1650'],
  [1683, 'O1683'], [1717, 'O1683'], [1718, 'O1683'], [1739, 'O1683'], [1740, 'O1683'], [1759, 'O1683'],
  [1760, 'O1760'], [1779, 'O1760'], [1780, 'O1780'], [1799, 'O1780'],
];

export const romaniaShapeFixes = {
  'roman-empire': ['mediterranean 70–395 in held steps: Dacia free to 105, Roman Dacia only (not the plain or Moldavia) 106–271, cut back to the Danube after'],
  'ottoman-empire': ['anatolia-balkans 1475–1799 in held steps, cut back from Wallachia, Moldavia and Transylvania'],
};

const INF = { start: -Infinity, end: Infinity };
const closed = (r) => (r[0][0] === r[r.length - 1][0] && r[0][1] === r[r.length - 1][1] ? r : [...r, r[0]]);
const resolveInline = (r) => (r && typeof r === 'object' && Array.isArray(r.ring) ? ensureClockwise(closed(r.ring)) : null);
const checksum = (ring) => ring.reduce((s, [x, y]) => s + x * 7 + y * 13, 0);

function replan(entities, id, rid, lo, hi, plan, rings, sums) {
  const ent = entities.find((e) => e.id === id);
  if (!ent) throw new Error(`romania fixes: no entity ${id}`);
  const src = { ...ent, overlays: ent.overlays.slice() };
  for (const o of src.overlays) {
    for (const r of o.regions) if (typeof r === 'string' || !Array.isArray(r.ring)) throw new Error(`romania fixes: ${id} ${o.year} has a region without an inline ring`);
  }
  // A held step is a [start, end] pair sharing a key. Holes are held from the start year (so a
  // hole sized for a later morph never meets the held ring), which keeps Day 87's Habsburg
  // Serbia hole (1718–1739) in its own step.
  const seen = new Set();
  let stepHoles = [];
  let open = false;
  const made = plan.map(([y, key], i) => {
    const parts = morphEntityAtYear(src, y, resolveInline, INF, 20, resolveRegionHoles);
    const part = parts.find((p) => p.regionId === rid);
    if (!part) throw new Error(`romania fixes: ${id} has no ${rid} at ${y}`);
    if (open) open = false; // the end year of a held step keeps the start year's holes
    else {
      stepHoles = part.holes;
      open = plan[i + 1]?.[1] === key;
    }
    if (!seen.has(key)) {
      seen.add(key);
      if (Math.abs(checksum(part.ring) - sums[key]) > 1e-6) throw new Error(`romania fixes: ${id} ${rid} at ${y} changed — regenerate the ${key} trim`);
    }
    if (!rings[key]) throw new Error(`romania fixes: missing trim ${key}`);
    let base = src.overlays[0];
    for (const o of src.overlays) if (o.year <= y) base = o;
    const regions = parts.map((p) => {
      const holes = p.regionId === rid ? stepHoles : p.holes;
      return { id: p.regionId, name: p.regionName, ring: p.regionId === rid ? rings[key] : p.ring, ...(holes.length ? { holes } : {}) };
    });
    return { year: y, label: base.label, approximation: base.approximation, regions };
  });
  ent.overlays = [...src.overlays.filter((o) => o.year <= lo || o.year >= hi), ...made].sort((a, b) => a.year - b.year);
}

/** Cut the Roman and Ottoman rings back from the pack's lands (run after the Serbia fixes). */
export function applyRomaniaShapeFixes(entities) {
  replan(entities, 'roman-empire', 'mediterranean', 50, 400, ROMAN_PLAN, ROMAN_TRIM_RINGS, ROMAN_SUM);
  replan(entities, 'ottoman-empire', 'anatolia-balkans', 1453, 1800, OTT_PLAN, OTT_TRIM_RINGS, OTT_SUM);
  // Roman Dacia (106–271) is drawn by the Roman ring: link it to the Romania timeline.
  const rome = entities.find((e) => e.id === 'roman-empire');
  if (!rome.timelineItemIds.includes('ro-roman-dacia')) rome.timelineItemIds = [...rome.timelineItemIds, 'ro-roman-dacia'];
}
